-- ============================================================
-- VARIANT: single-belief actuals (spec 6.1) -- only for pipelines you own,
-- where a second belief is a defect. PK admits one belief per target; the
-- belief_guard trigger (function ships in the catalog) makes the upsert
-- write skip-or-raise. Use IN PLACE OF the actuals block above.
-- Generated by: forecast-store ddl --section tables --single-belief-actuals --timescale
-- ============================================================

CREATE TABLE IF NOT EXISTS forecast.actuals (
    series_id    bigint NOT NULL,
    target_time  timestamptz NOT NULL,
    available_at timestamptz NOT NULL DEFAULT now(),
    recorded_at  timestamptz NOT NULL DEFAULT now(),
    value        double precision,
    PRIMARY KEY (series_id, target_time)
);

CREATE OR REPLACE TRIGGER belief_guard BEFORE UPDATE ON forecast.actuals
FOR EACH ROW EXECUTE FUNCTION forecast.belief_guard();

