-- ============================================================
-- VARIANT: an additional forecast-log instance with its own band (spec 7.2)
-- -- e.g. a decile-only model. Name and band are yours; columns derive from
-- the band by the bijection (q10 <-> 0.1). Add ALONGSIDE the blocks above.
-- Generated by: python -c "...ForecastLogSpec('forecasts_deciles',
--   quantile_band=('0.1','0.3','0.5','0.7','0.9'), has_mean=False)..."
-- ============================================================

CREATE TABLE IF NOT EXISTS forecast.forecasts_deciles (
    run_id       uuid NOT NULL,           -- no FK by default; see spec §8
    series_id    bigint NOT NULL,
    target_time  timestamptz NOT NULL,
    available_at timestamptz NOT NULL,    -- denormalized from the run (writable claim)
    recorded_at  timestamptz NOT NULL DEFAULT now(),  -- system clock (never written)
    q10           double precision,
    q30           double precision,
    q50           double precision,
    q70           double precision,
    q90           double precision,
    PRIMARY KEY (series_id, target_time, run_id)
);

CREATE INDEX IF NOT EXISTS forecasts_deciles_asof_idx
    ON forecast.forecasts_deciles (series_id, target_time, available_at DESC);

CREATE OR REPLACE VIEW forecast.latest_forecasts_deciles AS
SELECT DISTINCT ON (f.series_id, f.target_time)
       s.name AS series_name,
       f.series_id, f.target_time, f.available_at, f.run_id,
       f.q10, f.q30, f.q50, f.q70, f.q90
FROM forecast.forecasts_deciles f
JOIN forecast.series s USING (series_id)
ORDER BY f.series_id, f.target_time, f.available_at DESC;

